# TtZipError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class TtZipError(Exception):
    """
    Typed error enum mapped directly to Swift `throws TTZipError`.
    """

    pass

_UniffiTempTtZipError = TtZipError

class TtZipError:  # type: ignore
    """
    Typed error enum mapped directly to Swift `throws TTZipError`.
    """

    class FileNotFound(_UniffiTempTtZipError):
        def __init__(self, path):
            super().__init__(", ".join([
                "path={!r}".format(path),
            ]))
            self.path = path

        def __repr__(self):
            return "TtZipError.FileNotFound({})".format(str(self))
    _UniffiTempTtZipError.FileNotFound = FileNotFound # type: ignore
    class InvalidPassword(_UniffiTempTtZipError):
        def __init__(self):
            pass

        def __repr__(self):
            return "TtZipError.InvalidPassword({})".format(str(self))
    _UniffiTempTtZipError.InvalidPassword = InvalidPassword # type: ignore
    class CorruptHeader(_UniffiTempTtZipError):
        def __init__(self, details, offset):
            super().__init__(", ".join([
                "details={!r}".format(details),
                "offset={!r}".format(offset),
            ]))
            self.details = details
            self.offset = offset

        def __repr__(self):
            return "TtZipError.CorruptHeader({})".format(str(self))
    _UniffiTempTtZipError.CorruptHeader = CorruptHeader # type: ignore
    class SecurityViolation(_UniffiTempTtZipError):
        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "TtZipError.SecurityViolation({})".format(str(self))
    _UniffiTempTtZipError.SecurityViolation = SecurityViolation # type: ignore
    class EngineError(_UniffiTempTtZipError):
        def __init__(self, code):
            super().__init__(", ".join([
                "code={!r}".format(code),
            ]))
            self.code = code

        def __repr__(self):
            return "TtZipError.EngineError({})".format(str(self))
    _UniffiTempTtZipError.EngineError = EngineError # type: ignore
    class IoError(_UniffiTempTtZipError):
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "TtZipError.IoError({})".format(str(self))
    _UniffiTempTtZipError.IoError = IoError # type: ignore
    class Cancelled(_UniffiTempTtZipError):
        def __init__(self):
            pass

        def __repr__(self):
            return "TtZipError.Cancelled({})".format(str(self))
    _UniffiTempTtZipError.Cancelled = Cancelled # type: ignore

TtZipError = _UniffiTempTtZipError # type: ignore
del _UniffiTempTtZipError


class _UniffiConverterTypeTtZipError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return TtZipError.FileNotFound(
                _UniffiConverterString.read(buf),
            )
        if variant == 2:
            return TtZipError.InvalidPassword(
            )
        if variant == 3:
            return TtZipError.CorruptHeader(
                _UniffiConverterString.read(buf),
                _UniffiConverterUInt64.read(buf),
            )
        if variant == 4:
            return TtZipError.SecurityViolation(
                _UniffiConverterString.read(buf),
            )
        if variant == 5:
            return TtZipError.EngineError(
                _UniffiConverterInt32.read(buf),
            )
        if variant == 6:
            return TtZipError.IoError(
                _UniffiConverterString.read(buf),
            )
        if variant == 7:
            return TtZipError.Cancelled(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, TtZipError.FileNotFound):
            _UniffiConverterString.check_lower(value.path)
            return
        if isinstance(value, TtZipError.InvalidPassword):
            return
        if isinstance(value, TtZipError.CorruptHeader):
            _UniffiConverterString.check_lower(value.details)
            _UniffiConverterUInt64.check_lower(value.offset)
            return
        if isinstance(value, TtZipError.SecurityViolation):
            _UniffiConverterString.check_lower(value.reason)
            return
        if isinstance(value, TtZipError.EngineError):
            _UniffiConverterInt32.check_lower(value.code)
            return
        if isinstance(value, TtZipError.IoError):
            _UniffiConverterString.check_lower(value.message)
            return
        if isinstance(value, TtZipError.Cancelled):
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, TtZipError.FileNotFound):
            buf.write_i32(1)
            _UniffiConverterString.write(value.path, buf)
        if isinstance(value, TtZipError.InvalidPassword):
            buf.write_i32(2)
        if isinstance(value, TtZipError.CorruptHeader):
            buf.write_i32(3)
            _UniffiConverterString.write(value.details, buf)
            _UniffiConverterUInt64.write(value.offset, buf)
        if isinstance(value, TtZipError.SecurityViolation):
            buf.write_i32(4)
            _UniffiConverterString.write(value.reason, buf)
        if isinstance(value, TtZipError.EngineError):
            buf.write_i32(5)
            _UniffiConverterInt32.write(value.code, buf)
        if isinstance(value, TtZipError.IoError):
            buf.write_i32(6)
            _UniffiConverterString.write(value.message, buf)
        if isinstance(value, TtZipError.Cancelled):
            buf.write_i32(7)





class UniFfiLicenseResult:
    """
    Verification result enumeration exposed to UniFFI.
    """

    def __init__(self):
        raise RuntimeError("UniFfiLicenseResult cannot be instantiated directly")

    # Each enum variant is a nested class of the enum itself.
    class VALID:
        payload: "UniFfiLicensePayload"

        def __init__(self,payload: "UniFfiLicensePayload"):
            self.payload = payload

        def __str__(self):
            return "UniFfiLicenseResult.VALID(payload={})".format(self.payload)

        def __eq__(self, other):
            if not other.is_valid():
                return False
            if self.payload != other.payload:
                return False
            return True
    
    class INVALID_SIGNATURE:

        def __init__(self,):
            pass

        def __str__(self):
            return "UniFfiLicenseResult.INVALID_SIGNATURE()".format()

        def __eq__(self, other):
            if not other.is_invalid_signature():
                return False
            return True
    
    class MALFORMED_KEY:
        reason: "str"

        def __init__(self,reason: "str"):
            self.reason = reason

        def __str__(self):
            return "UniFfiLicenseResult.MALFORMED_KEY(reason={})".format(self.reason)

        def __eq__(self, other):
            if not other.is_malformed_key():
                return False
            if self.reason != other.reason:
                return False
            return True
    
    

    # For each variant, we have an `is_NAME` method for easily checking
    # whether an instance is that variant.
    def is_valid(self) -> bool:
        return isinstance(self, UniFfiLicenseResult.VALID)
    def is_invalid_signature(self) -> bool:
        return isinstance(self, UniFfiLicenseResult.INVALID_SIGNATURE)
    def is_malformed_key(self) -> bool:
        return isinstance(self, UniFfiLicenseResult.MALFORMED_KEY)
    

# Now, a little trick - we make each nested variant class be a subclass of the main
# enum class, so that method calls and instance checks etc will work intuitively.
# We might be able to do this a little more neatly with a metaclass, but this'll do.
UniFfiLicenseResult.VALID = type("UniFfiLicenseResult.VALID", (UniFfiLicenseResult.VALID, UniFfiLicenseResult,), {})  # type: ignore
UniFfiLicenseResult.INVALID_SIGNATURE = type("UniFfiLicenseResult.INVALID_SIGNATURE", (UniFfiLicenseResult.INVALID_SIGNATURE, UniFfiLicenseResult,), {})  # type: ignore
UniFfiLicenseResult.MALFORMED_KEY = type("UniFfiLicenseResult.MALFORMED_KEY", (UniFfiLicenseResult.MALFORMED_KEY, UniFfiLicenseResult,), {})  # type: ignore




class _UniffiConverterTypeUniFfiLicenseResult(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return UniFfiLicenseResult.VALID(
                _UniffiConverterTypeUniFfiLicensePayload.read(buf),
            )
        if variant == 2:
            return UniFfiLicenseResult.INVALID_SIGNATURE(
            )
        if variant == 3:
            return UniFfiLicenseResult.MALFORMED_KEY(
                _UniffiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value.is_valid():
            _UniffiConverterTypeUniFfiLicensePayload.check_lower(value.payload)
            return
        if value.is_invalid_signature():
            return
        if value.is_malformed_key():
            _UniffiConverterString.check_lower(value.reason)
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value.is_valid():
            buf.write_i32(1)
            _UniffiConverterTypeUniFfiLicensePayload.write(value.payload, buf)
        if value.is_invalid_signature():
            buf.write_i32(2)
        if value.is_malformed_key():
            buf.write_i32(3)
            _UniffiConverterString.write(value.reason, buf)





class ProgressHandler(typing.Protocol):
    """
    Callback interface protocol implemented in Swift.
    """

    def on_progress(self, processed_bytes: "int",total_bytes: "int",current_entry: "typing.Optional[str]"):
        raise NotImplementedError
# Magic number for the Rust proxy to call using the same mechanism as every other method,
# to free the callback once it's dropped by Rust.
_UNIFFI_IDX_CALLBACK_FREE = 0
# Return codes for callback calls
_UNIFFI_CALLBACK_SUCCESS = 0
_UNIFFI_CALLBACK_ERROR = 1
_UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

class _UniffiCallbackInterfaceFfiConverter:
    _handle_map = _UniffiHandleMap()

    @classmethod
    def lift(cls, handle):
        return cls._handle_map.get(handle)

    @classmethod
    def read(cls, buf):
        handle = buf.read_u64()
        cls.lift(handle)

    @classmethod
    def check_lower(cls, cb):
        pass

    @classmethod
    def lower(cls, cb):
        handle = cls._handle_map.insert(cb)
        return handle

    @classmethod
    def write(cls, cb, buf):
        buf.write_u64(cls.lower(cb))

# Put all the bits inside a class to keep the top-level namespace clean
class _UniffiTraitImplProgressHandler:
    # For each method, generate a callback function to pass to Rust

    @_UNIFFI_CALLBACK_INTERFACE_PROGRESS_HANDLER_METHOD0
    def on_progress(
            uniffi_handle,
            processed_bytes,
            total_bytes,
            current_entry,
            uniffi_out_return,
            uniffi_call_status_ptr,
        ):
        uniffi_obj = _UniffiConverterTypeProgressHandler._handle_map.get(uniffi_handle)
        def make_call():
            args = (_UniffiConverterUInt64.lift(processed_bytes), _UniffiConverterUInt64.lift(total_bytes), _UniffiConverterOptionalString.lift(current_entry), )
            method = uniffi_obj.on_progress
            return method(*args)

        
        def write_return_value(v):
            uniffi_out_return[0] = _UniffiConverterBool.lower(v)
        _uniffi_trait_interface_call(
                uniffi_call_status_ptr.contents,
                make_call,
                write_return_value,
        )

    @_UNIFFI_CALLBACK_INTERFACE_FREE
    def _uniffi_free(uniffi_handle):
        _UniffiConverterTypeProgressHandler._handle_map.remove(uniffi_handle)

    # Generate the FFI VTable.  This has a field for each callback interface method.
    _uniffi_vtable = _UniffiVTableCallbackInterfaceProgressHandler(
        on_progress,
        _uniffi_free
    )
    # Send Rust a pointer to the VTable.  Note: this means we need to keep the struct alive forever,
    # or else bad things will happen when Rust tries to access it.
    _UniffiLib.uniffi_ttzip_engine_fn_init_callback_vtable_progresshandler(ctypes.byref(_uniffi_vtable))

# The _UniffiConverter which transforms the Callbacks in to Handles to pass to Rust.
_UniffiConverterTypeProgressHandler = _UniffiCallbackInterfaceFfiConverter()



class _UniffiConverterOptionalString(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        if value is not None:
            _UniffiConverterString.check_lower(value)

    @classmethod
    def write(cls, value, buf):
        if value is None:
            buf.write_u8(0)
            return

        buf.write_u8(1)
        _UniffiConverterString.write(value, buf)

    @classmethod
    def read(cls, buf):
        flag = buf.read_u8()
        if flag == 0:
            return None
        elif flag == 1:
            return _UniffiConverterString.read(buf)
        else:
            raise InternalError("Unexpected flag byte for optional type")



